1	'use client';
2	
3	import Image from 'next/image';
4	import { useCallback, useEffect, useState } from 'react';
5	import useEmblaCarousel from 'embla-carousel-react';
6	import styles from './portfolio-carousel.module.css';
7	
8	interface Slide {
9	  label: string;
10	  labelVariant: string;
11	  cardVariant: string;
12	  imageOuterVariant: string;
13	  imageSrc: string;
14	  imageAlt: string;
15	  imageWidth: number;
16	  imageHeight: number;
