18	
19	const SLIDES: Slide[] = [
20	  {
21	    label: 'Shopify',
22	    labelVariant: 'heading-3-green',
23	    cardVariant: 'cream',
24	    imageOuterVariant: 'green',
25	    imageSrc: '/images/webflow/69662a202a4c0d57bdf2c10b_Home.png',
26	    imageAlt: 'Portfolio Image',
27	    imageWidth: 843,
28	    imageHeight: 690,
29	  },
30	  {
31	    label: 'WordPress',
32	    labelVariant: 'heading-3-green-light',
33	    cardVariant: 'light-green',
34	    imageOuterVariant: 'green-light',
35	    imageSrc: '/images/webflow/Travel.png',
36	    imageAlt: 'TravelPerk corporate travel management website template built by Boldteq',
37	    imageWidth: 840,
