62	// Duplicate for seamless loop
63	const ALL_SLIDES = [...SLIDES, ...SLIDES];
64	
65	export function PortfolioCarousel() {
66	  const [emblaRef, emblaApi] = useEmblaCarousel({
67	    loop: true,
68	    align: 'start',
69	    dragFree: false,
70	    slidesToScroll: 1,
71	  });
72	  const [selectedIndex, setSelectedIndex] = useState(0);
73	
74	  const scrollPrev = useCallback(() => emblaApi?.scrollPrev(), [emblaApi]);
75	  const scrollNext = useCallback(() => emblaApi?.scrollNext(), [emblaApi]);
76	  const scrollTo = useCallback((i: number) => emblaApi?.scrollTo(i), [emblaApi]);
77	
78	  useEffect(() => {
79	    if (!emblaApi) return;
80	    const onSelect = () => setSelectedIndex(emblaApi.selectedScrollSnap() % SLIDES.length);
81	    emblaApi.on('select', onSelect);
82	    onSelect();
83	    return () => { emblaApi.off('select', onSelect); };
84	  }, [emblaApi]);
85	
86	  return (
87	    <section
88	      className={`${styles['section-regular-2']} ${styles['img-slider-sec']}`}
89	    >
90	      <div className={styles['column-4x-large']} style={{ alignItems: 'center' }}>
91	        {/* Slider container — relative for arrow positioning */}
92	        <div style={{ position: 'relative', width: '100%' }}>
93	          {/* Embla viewport */}
94	          <div ref={emblaRef} className={styles['gallery-13-mask']}>
95	            {/* Track */}
96	            <div className={styles['gallery-13-track']}>
97	              {ALL_SLIDES.map((slide, i) => (
98	                <div
99	                  key={`${slide.label}-${i}`}
100	                  className={styles['gallery-13-slide']}
101	                >
102	                  <div
103	                    className={`${styles['gallery-13-card']} ${styles[slide.cardVariant]}`}
104	                  >
105	                    {/* Image outer */}
106	                    <div
107	                      className={`${styles['gallery-image-outer']} ${styles[slide.imageOuterVariant]}`}
108	                    >
109	                      <Image
110	                        src={slide.imageSrc}
111	                        alt={slide.imageAlt}
112	                        width={slide.imageWidth}
113	                        height={slide.imageHeight}
114	                        loading="lazy"
115	                        className={`${styles['image-cover']} ${styles['radius-0']}`}
116	                      />
117	                    </div>
118	                    {/* Caption */}
119	                    <div className={styles['gallery-13-caption']}>
120	                      <div className={`${styles['heading-3']} ${styles[slide.labelVariant]}`}>
121	                        {slide.label}
122	                      </div>
123	                    </div>
124	                  </div>
125	                </div>
126	              ))}
127	            </div>
128	          </div>
129	
130	          {/* Prev button */}
131	          <button
132	            onClick={scrollPrev}
133	            aria-label="Previous slide"
134	            className={`${styles['gallery-13-button']} ${styles['button-left']}`}
135	          >
136	            <div className={styles['icon-button-outline-large']}>
137	              <span className={`${styles['icon-regular']} ${styles['icon-blue']}`}>
138	                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
139	                  <path d="M7.82843 10.9999H20V12.9999H7.82843L13.1924 18.3638L11.7782 19.778L4 11.9999L11.7782 4.22168L13.1924 5.63589L7.82843 10.9999Z" fill="currentColor" />
140	                </svg>
141	              </span>
142	            </div>
143	          </button>
144	
145	          {/* Next button */}
146	          <button
147	            onClick={scrollNext}
148	            aria-label="Next slide"
149	            className={`${styles['gallery-13-button']} ${styles['button-right']}`}
150	          >
151	            <div className={styles['icon-button-outline-large']}>
152	              <span className={`${styles['icon-regular']} ${styles['icon-blue']}`}>
153	                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
154	                  <path d="M16.1716 10.9999L10.8076 5.63589L12.2218 4.22168L20 11.9999L12.2218 19.778L10.8076 18.3638L16.1716 12.9999H4V10.9999H16.1716Z" fill="currentColor" />
155	                </svg>
156	              </span>
157	            </div>
158	          </button>
159	        </div>
160	
161	        {/* Dot navigation */}
162	        <div className={styles['slider-dots']}>
163	          {SLIDES.map((_, i) => (
164	            <button
165	              key={i}
166	              onClick={() => scrollTo(i)}
167	              aria-label={`Go to slide ${i + 1}`}
168	              className={`${styles['slider-dot']}${i === selectedIndex ? ` ${styles['slider-dot-active']}` : ''}`}
169	            />
170	          ))}
171	        </div>
172	      </div>
173	
174	      <div className={styles['container-large-2']} />
175	    </section>
176	  );
177	}
