/* ============================================================
   CTA BANNER — cta-banner.module.css
   Matches Webflow .blue-sec + .book-section.remove-pattern
   ============================================================ */

/* Outer section wrapper */
.ctaSection {
  background-color: transparent;
  margin-bottom: 70px;
  padding: 0 5%;
  position: relative;
}

/* Inner card — navy background */
.ctaCard {
  background-color: #082753;
  background-image: url('/images/webflow/Union.svg');
  background-position: 100% 100%;
  background-repeat: no-repeat;
  background-size: auto;
  border-radius: 20px;
  padding: 40px 20px 50px;
  max-width: 1280px;
  margin: 0 auto;
  text-align: center;
}

/* Left-aligned variant */
.ctaCardLeft {
  text-align: left;
}

/* Content width cap (left layout only) */
.ctaContent {
  max-width: 700px;
}

/* Centered: no width cap */
.ctaContentCentered {
  max-width: none;
}

/* Heading */
.ctaHeading {
  color: #ffffff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 45px;
  margin: 0;
}

/* Subtitle paragraph */
.ctaSubtitle {
  color: rgba(255, 255, 255, 0.7);
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  margin-top: 16px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* Left layout: subtitle — no auto margins */
.ctaSubtitleLeft {
  margin-left: 0;
  margin-right: 0;
  max-width: none;
}

/* Bullet list row (beta page) */
.ctaBullets {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin-top: 20px;
}

/* Single bullet item */
.ctaBulletItem {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #fff;
  margin-bottom: 2px;
}

.ctaBulletIcon {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.ctaBulletText {
  color: #fff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  margin: 0;
}

/* CTA button row */
.ctaActions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
  margin-top: 32px;
  flex-wrap: wrap;
}

.ctaActionsLeft {
  justify-content: flex-start;
}

/* Primary CTA — gradient button */
.ctaPrimary {
  color: #fff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0.75rem 1.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* Left layout — primary button: no icon background-image */
.ctaPrimaryLeft {
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 0 0;
}

/* Secondary CTA — white ghost button */
.ctaSecondary {
  color: #019ae6;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  background-color: #fff;
  background-image: url('/images/webflow/Group-46729-1.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: auto;
  border-radius: 0.75rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

import Link from "next/link";
import Image from "next/image";
import styles from "./cta-banner.module.css";

/*
  Matches Webflow .blue-sec + .book-section.remove-pattern
  - Centered layout (default): used on blog, how-it-works, scope, testimonials
  - Left-aligned layout (align="left"): used on beta page with bullets
*/
export function CtaBanner({
  title = "Ready to Deliver This Level of Work Under Your Brand?",
  subtitle = "Partner with Boldteq as your dedicated backend delivery team and gain a reliable, scalable foundation for your technology initiatives.",
  primaryCta = { label: "Book a Demo", href: "/book-a-demo" },
  secondaryCta,
  bullets,
  align = "center",
}: {
  title?: string;
  subtitle?: string;
  primaryCta?: { label: string; href: string };
  secondaryCta?: { label: string; href: string };
  bullets?: string[];
  align?: "center" | "left";
}) {
  const isLeft = align === "left";

  return (
    <section className={styles.ctaSection}>
      <div className={`${styles.ctaCard}${isLeft ? ` ${styles.ctaCardLeft}` : ""}`}>
        <div className={isLeft ? styles.ctaContent : styles.ctaContentCentered}>
          <h2 className={styles.ctaHeading}>{title}</h2>

          {subtitle && (
            <p className={`${styles.ctaSubtitle}${isLeft ? ` ${styles.ctaSubtitleLeft}` : ""}`}>
              {subtitle}
            </p>
          )}

          {/* Bullet list (beta page) */}
          {bullets && bullets.length > 0 && (
            <div className={styles.ctaBullets}>
              {bullets.map((bullet) => (
                <div key={bullet} className={styles.ctaBulletItem}>
                  <div className={styles.ctaBulletIcon}>
                    <Image
                      src="/images/webflow/Group-1.svg"
                      alt="Check Icon"
                      width={14}
                      height={14}
                    />
                  </div>
                  <p className={styles.ctaBulletText}>{bullet}</p>
                </div>
              ))}
            </div>
          )}

          <div className={`${styles.ctaActions}${isLeft ? ` ${styles.ctaActionsLeft}` : ""}`}>
            <Link
              href={primaryCta.href}
              className={`${styles.ctaPrimary}${isLeft ? ` ${styles.ctaPrimaryLeft}` : ""}`}
            >
              {primaryCta.label}
            </Link>

            {secondaryCta && (
              <Link href={secondaryCta.href} className={styles.ctaSecondary}>
                {secondaryCta.label}
              </Link>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}

