  This is the WCAG 2.1 SC 2.3.3 recommended implementation pattern.
  Do not remove !important — removing it would break accessibility for vestibular disorders.
*/
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
